export function diagram(p,hint=0,heightShown=false){const d=p.diagramData;if(!d)return '';let verts=d.vertices,pts=[...verts,...(d.foot?[d.foot]:[])],xs=pts.map(v=>v[0]),ys=pts.map(v=>v[1]),minX=Math.floor(Math.min(...xs))-1,maxX=Math.ceil(Math.max(...xs))+1,minY=Math.floor(Math.min(...ys))-1,maxY=Math.ceil(Math.max(...ys))+1,s=Math.min(390/(maxX-minX),210/(maxY-minY)),ox=300-(maxX+minX)*s/2,oy=145+(maxY+minY)*s/2;const xy=([x,y])=>[ox+x*s,oy-y*s],point=v=>xy(v).join(','),line=(a,b,extra='')=>`<line x1="${xy(a)[0]}" y1="${xy(a)[1]}" x2="${xy(b)[0]}" y2="${xy(b)[1]}" ${extra}/>`;const text=(v,t,dx=0,dy=0)=>`<text x="${xy(v)[0]+dx}" y="${xy(v)[1]+dy}" text-anchor="middle">${t}</text>`;let grid='';if(d.grid){for(let x=minX;x<=maxX;x++)grid+=line([x,minY],[x,maxY],'stroke="#dce6e7" stroke-width="1"');for(let y=minY;y<=maxY;y++)grid+=line([minX,y],[maxX,y],'stroke="#dce6e7" stroke-width="1"')}
let body=`<polygon points="${verts.map(point).join(' ')}" fill="#56ac9635" stroke="#218876" stroke-width="2.5" stroke-linejoin="round"/>`,labels='';if(d.oblique&&hint>=2){const loX=Math.min(...xs),hiX=Math.max(...xs),loY=Math.min(...ys),hiY=Math.max(...ys);body+=line([loX,loY],[hiX,loY],'class="height" stroke-width="2"')+line([hiX,loY],[hiX,hiY],'class="height" stroke-width="2"')+line([hiX,hiY],[loX,hiY],'class="height" stroke-width="2"')+line([loX,hiY],[loX,loY],'class="height" stroke-width="2"')}if(d.kind==='triangle'){const [a,b,c]=verts,f=d.foot,mid=[(a[0]+b[0])/2,(a[1]+b[1])/2],hm=[(f[0]+c[0])/2,(f[1]+c[1])/2],u=[(b[0]-a[0])/d.b,(b[1]-a[1])/d.b],v=[(c[0]-f[0])/d.h,(c[1]-f[1])/d.h],r=10/s,side=f[0]*u[0]+f[1]*u[1]>d.b/2?-1:1;body+=line(a,b,'stroke="#127565" stroke-width="4"');if(!d.grid||heightShown||hint>1){body+=line(a,f,'stroke="#829e97" stroke-width="1.5" stroke-dasharray="5 5"')+line(c,f,'class="height" stroke-width="2"');let z=[f[0]+u[0]*r*side,f[1]+u[1]*r*side],q=[z[0]+v[0]*r,z[1]+v[1]*r],t=[f[0]+v[0]*r,f[1]+v[1]*r];body+=`<polyline points="${[z,q,t].map(point).join(' ')}" fill="none" stroke="#ca8c49" stroke-width="1.7"/>`;if(!d.grid)labels+=text(hm,`h = ${d.hide==='height'?'?':d.h} ${d.unit}`,Math.min(...pts.map(v=>xy(v)[0]))-65-xy(hm)[0],0)}if(!d.grid)labels+=text(mid,`b = ${d.hide==='base'?'?':d.b} ${d.unit}`,-v[0]*28,v[1]*28);body+=verts.map(v=>`<circle cx="${xy(v)[0]}" cy="${xy(v)[1]}" r="3.5" fill="#197968"/>`).join('');if(d.grid)labels+=text([minX,minY],'1 grid square = 1 square unit',110,24)}else{labels+=text([d.w/2,0],`${d.w} units`,0,28)+text([0,d.h/2],`${d.h} units`,-43,0);if(hint>=2){body+=`<rect x="${xy([0,d.h])[0]}" y="${xy([0,d.h])[1]}" width="${d.w*s}" height="${d.h*s}" fill="none" stroke="#d89445" stroke-width="2" stroke-dasharray="6 5"/>`;if(d.shape==='trapezoid')body+=line([d.c,0],[d.c,d.h],'class="height" stroke-width="2"')+line([d.w-d.c,0],[d.w-d.c,d.h],'class="height" stroke-width="2"');if(d.shape==='roof')body+=line([0,d.h-d.c],[d.w,d.h-d.c],'class="height" stroke-width="2"')}if(hint>=3)labels+=text([d.w-d.c/2,d.h],`${d.c} units`,0,-18)}const labelBounds=[...labels.matchAll(/<text x="([\d.e+-]+)"[^>]*>([^<]*)<\/text>/g)].map(m=>({x:Number(m[1]),half:m[2].length*6.3}));const allX=pts.map(v=>xy(v)[0]);const left=Math.min(...allX,...labelBounds.map(t=>t.x-t.half))-18,right=Math.max(...allX,...labelBounds.map(t=>t.x+t.half))+18;return `<div class="diagram"><svg viewBox="${left} 0 ${right-left} 310" role="img" aria-label="${d.kind==='triangle'?'Triangle with selected base and perpendicular altitude':'Polygon on a unit grid'}">${grid}${body}${labels}</svg></div>`}
export function shapeSVG(s){return `<svg viewBox="0 0 80 75" aria-hidden="true"><path d="${s.path}" fill="${s.id==='open'||s.id==='cube'?'none':'#4aab9130'}" stroke="#287d6c" stroke-width="2.5" stroke-linejoin="round"/></svg>`}



